export function generateDockerignore(targetName?: string): string {
  const generatedTargets = targetName
    ? [
        "!.biodome-build/targets/",
        ".biodome-build/targets/*",
        `!.biodome-build/targets/${targetName}/`,
        `!.biodome-build/targets/${targetName}/**`,
      ]
    : ["!.biodome-build/targets", "!.biodome-build/targets/**"];
  return [
    "# Auto-generated by biodome",
    "# These files are not needed inside the Docker build context.",
    "",
    ".git",
    ".gitignore",
    ".biodome/node_modules/",
    ".biodome-build/*",
    "!.biodome-build/supervisord.conf",
    "!.biodome-build/startup.sh",
    ...generatedTargets,
    ".biodome-build/targets/*/artifacts/",
    ".biodome-build/targets/*/logs/",
    ".biodome-build/targets/*/manifest.json",
    ".biodome-build/targets/*/state.json",
    ".biodome-build/targets/*/ready",
    ".data",
    "node_modules",
    "**/node_modules",
    ".venv",
    "**/.venv",
    "venv",
    "**/venv",
    "__pycache__",
    "*.pyc",
    "*.pyo",
    "target",
    "*.log",
    ".env",
    ".env.*",
    "*.env",
    "**/.env",
    "**/.env.*",
    "**/*.env",
    ".aws/",
    "**/.aws/",
    ".ssh/",
    "**/.ssh/",
    ".netrc",
    "**/.netrc",
    ".npmrc",
    "**/.npmrc",
    ".pypirc",
    "**/.pypirc",
    "*.pem",
    "*.key",
    "Dockerfile",
    ".dockerignore",
    "docker-compose.yaml",
    "docker-compose.yml",
    "",
  ].join("\n");
}
